// Running. Rounds of fan-out are serialized here, in number order. The
// partial unique index promotion_rollouts_running_key is the final guard:
// two claims that both pass this statement's checks cannot both commit. No
// row is returned when the rollout is not Pending or not next; a unique
// violation says another rollout of the Stage is Running.
func (q *Queries) StartPromotionRollout(ctx context.Context, id uuid.UUID) (PromotionRolloutRow, error) {
	row := q.db.QueryRow(ctx, startPromotionRollout, id)
	var i PromotionRolloutRow
	err := row.Scan(
		&i.ID,
		&i.ProjectName,
		&i.Name,
		&i.StageName,
		&i.Number,
		&i.FreightName,
		&i.MaxConcurrent,
		&i.MaxFailures,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.TargetsResolvedAt,
		&i.StatusPhase,
		&i.StatusReason,
		&i.StatusMessage,
		&i.StatusStartedAt,
		&i.StatusFinishedAt,
	)
	return i, err
}

const updatePromotionRolloutStatus = `-- name: UpdatePromotionRolloutStatus :one
UPDATE promotion_rollouts SET
    status_phase = $1::text,
    status_reason = $2::text,
    status_message = $3::text,
    status_started_at = $4::timestamptz,
    status_finished_at = $5::timestamptz,
    updated_at = GREATEST(clock_timestamp(), updated_at + interval '1 microsecond')
WHERE project_name = $6
    AND name = $7
    AND ($8::uuid IS NULL OR id = $8)
    AND (
        $9::timestamptz IS NULL
        OR updated_at = $9
    )
RETURNING id, project_name, name, stage_name, number, freight_name, max_concurrent, max_failures, created_by, created_at, updated_at, targets_resolved_at, status_phase, status_reason, status_message, status_started_at, status_finished_at
`

type UpdatePromotionRolloutStatusParams struct {
	StatusPhase      string
	StatusReason     string
	StatusMessage    string
	StatusStartedAt  *time.Time
	StatusFinishedAt *time.Time
	ProjectName      string
	Name             string
	ID               *uuid.UUID
	UpdatedAt        *time.Time
}

// updated_at doubles as the row's version, so it must grow with every write
// to a row even across a clock step or two writes in one microsecond. A
// non-null id or updated_at is a precondition; a row that fails one is left
// alone and nothing is returned.
func (q *Queries) UpdatePromotionRolloutStatus(ctx context.Context, arg UpdatePromotionRolloutStatusParams) (PromotionRolloutRow, error) {
	row := q.db.QueryRow(ctx, updatePromotionRolloutStatus,
		arg.StatusPhase,
		arg.StatusReason,
		arg.StatusMessage,
		arg.StatusStartedAt,
		arg.StatusFinishedAt,
		arg.ProjectName,
		arg.Name,
		arg.ID,
		arg.UpdatedAt,
	)
	var i PromotionRolloutRow
	err := row.Scan(
		&i.ID,
		&i.ProjectName,
		&i.Name,
		&i.StageName,
		&i.Number,
		&i.FreightName,
		&i.MaxConcurrent,
		&i.MaxFailures,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.TargetsResolvedAt,
		&i.StatusPhase,
		&i.StatusReason,
		&i.StatusMessage,
		&i.StatusStartedAt,
		&i.StatusFinishedAt,
	)
	return i, err
}
